def rotate_items(items, k):
    values = list(items)
    if values:
        k %= len(values)
        values = values[-k:] + values[:-k]
    return values

def interleave(left, right):
    for left_item, right_item in zip(left, right):
        yield left_item
        yield right_item

def find_products(products, query):
    return sorted(
        (product for product in products if query in product["name"]),
        key=lambda product: product["score"],
        reverse=True,
    )

def group_words(words):
    groups = {}
    for word in words:
        groups.setdefault(word[0], []).append(word)
    return groups

from datetime import date

def nearest_date(dates, target):
    target_date = date.fromisoformat(target)
    return min(dates, key=lambda d: abs((date.fromisoformat(d) - target_date).days))

def median_value(values):
    ordered = sorted(values)
    if not ordered:
        raise ValueError("median of empty sequence")
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    if not ranges:
        return []

    sorted_ranges = sorted(ranges, key=lambda r: r[0])
    merged = [[sorted_ranges[0][0], sorted_ranges[0][1]]]

    for start, end in sorted_ranges[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

def shortest_path(graph, start, goal):
    from collections import deque

    if start == goal:
        return [start]

    queue = deque([start])
    previous = {start: None}

    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor in previous:
                continue
            previous[neighbor] = node
            if neighbor == goal:
                path = [goal]
                while previous[path[-1]] is not None:
                    path.append(previous[path[-1]])
                return path[::-1]
            queue.append(neighbor)

    return None

def topological_order(nodes, edges):
    nodes = list(nodes)
    adjacency = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for source, destination in edges:
        adjacency[source].append(destination)
        in_degree[destination] += 1

    queue = [node for node in nodes if in_degree[node] == 0]
    order = []
    index = 0

    while index < len(queue):
        node = queue[index]
        index += 1
        order.append(node)

        for neighbor in adjacency[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return order
